mapper.select:
SELECT id AS store_id, merchant_id
FROM merchant_store
WHERE id = #{storeId}

SELECT m.id AS merchant_id,
       m.owner_user_id,
       m.status AS merchant_status,
       s.id AS store_id,
       s.status AS store_status
FROM merchant m
INNER JOIN merchant_store s ON s.merchant_id = m.id
WHERE m.id = #{merchantId}
  AND s.id = #{storeId}
  AND m.owner_user_id = #{ownerUserId}
